        if not settings.USE_TZ:
            return field_name
        if not self._tzname_re.match(tzname):
            raise ValueError("Invalid time zone name: %s" % tzname)

        db_tz = self.connection.timezone_name
        if db_tz == tzname:
            return field_name

        # Convert from database timezone to local time, returning TIMESTAMP WITH TIME ZONE
        # and cast it back to TIMESTAMP to strip the TIME ZONE details.
        return "CAST((FROM_TZ(%s, '%s') AT TIME ZONE '%s') AS TIMESTAMP)" % (field_name, db_tz, tzname)<|"|>,old_string:<|"|>    def _convert_field_to_tz(self, field_name, tzname):
